// Probe — verifies the geometry claims before writing to_fix.md.
import { ballSpeed, makeBricks, createState, step, collides, BALL_R, BRICK_H, BRICK_GAP, BRICK_TOP, PADDLE_Y, PADDLE_H, PADDLE_W, WIDTH } from '../game/neon.js';

const log = (k, v) => console.log(`${k.padEnd(58)} ${v}`);

// --- 1. Tunneling threshold through a brick (h + 2r) -----------------------
const slab = BRICK_H + 2 * BALL_R; // 20 + 14
log('brick slab (h + 2r)', slab);
for (let l = 1; l <= 8; l++) {
  const step = ballSpeed(l) * 0.05;
  log(`level ${l}: max step @50ms`, `${step.toFixed(1)} px  ${step > slab ? '> 34 -> TUNNEL' : 'ok'}`);
}

// --- 2. Grid: can the ball straddle a seam? (diameter vs gap) ---------------
const pitchY = BRICK_H + BRICK_GAP;
log('row pitch', pitchY);
log('ball diameter vs brick gap', `${2 * BALL_R} vs ${BRICK_GAP} -> ${2 * BALL_R > BRICK_GAP ? 'STRADDLES seams' : 'fits'}`);

// --- 3. Paddle discrete window ----------------------------------------------
log('paddle slab (h + 2r)', PADDLE_H + 2 * BALL_R);
log('paddle bounce window height (old code)', PADDLE_H);
for (const l of [1, 2, 4]) {
  const step = ballSpeed(l) * 0.05;
  log(`level ${l}: step vs paddle window`, `${step.toFixed(1)} px vs 12 px window -> ${step > PADDLE_H ? 'CAN SKIP window' : 'ok'}`);
}

// --- 4. TODAY's behavior: the ball passes straight through bricks -----------
{
  const state = createState(1);
  const brick = state.bricks.find((b) => b.row === 4); // bottom row, y=160..180
  // Ball below the brick, moving up, hits the bottom face mid-step.
  state.ball = { x: brick.x + brick.w / 2, y: brick.y + brick.h + 10, r: BALL_R, vx: 0, vy: -ballSpeed(1) };
  const before = { ...state.ball };
  step(state, 1 / 60);
  const after = { ...state.ball };
  const overlapped = collides(state.ball, brick);
  log('D1 today: ball moving up into brick bottom face', `vy before ${before.vy} -> vy after ${after.vy} (never flipped), brick alive ${brick.alive}, ball overlaps brick at end: ${overlapped}`);
}

// --- 5. D4: full traversal at level 7 speed (40 px) -------------------------
{
  const state = createState(1);
  state.bricks = [{ x: 100, y: 100, w: 72, h: 20, alive: true }];
  state.ball = { x: 136, y: 132, r: 7, vx: 0, vy: -800 };
  step(state, 0.05); // 40 px up -> y = 92
  const b = state.bricks[0];
  log('D4 today: 40px step crosses the 34px brick', `ball y=${state.ball.y.toFixed(1)} (above brick top 100? ${state.ball.y + 7 < 100}), brick alive ${b.alive}, overlap at end: ${collides(state.ball, b)} -> DISCRETE CHECK MISSES`);
}

// --- 6. D5: paddle pass-through at high speed -------------------------------
{
  const state = createState(7);
  state.ball = { x: WIDTH / 2, y: PADDLE_Y - BALL_R - 2, r: BALL_R, vx: 0, vy: ballSpeed(7) };
  const lost = step(state, 0.05); // 40 px down -> y = 479, bottom 486 > 460
  log('D5 today: fast ball crosses the paddle', `ball y=${state.ball.y.toFixed(1)} (bottom ${(state.ball.y + 7).toFixed(1)}), vy still ${state.ball.vy} (down), lost=${lost} -> PADDLE MISSED`);
}

// --- 7. D6: paddle bounce does not conserve speed ---------------------------
{
  const state = createState(1);
  state.ball = { x: state.paddle.x, y: PADDLE_Y - BALL_R - 4, r: BALL_R, vx: 0, vy: ballSpeed(1) }; // hit at far LEFT edge -> hit=-1
  step(state, 1 / 60);
  const norm = Math.hypot(state.ball.vx, state.ball.vy);
  log('D6 today: paddle edge hit (hit=-1)', `vx=${state.ball.vx.toFixed(1)}, vy=${state.ball.vy.toFixed(1)}, |v|=${norm.toFixed(2)} vs level speed ${ballSpeed(1)} -> ${norm > ballSpeed(1) + 0.01 ? 'SPEED INFLATED' : 'ok'}`);
}

// --- 8. D7: center hit -> vx = 0 ---------------------------------------------
{
  const state = createState(1);
  state.ball = { x: WIDTH / 2, y: PADDLE_Y - BALL_R - 4, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  step(state, 1 / 60);
  log('D7 today: center hit', `vx=${state.ball.vx} -> ${state.ball.vx === 0 ? 'ZERO: vertical loop' : 'ok'}`);
}

// --- 9. D3: seam straddle geometry on the real grid --------------------------
{
  const bricks = makeBricks(1);
  const a = bricks[1]; // col 1: x=84..156
  const b = bricks[2]; // col 2: x=164..236
  const seam = a.x + a.w + BRICK_GAP / 2; // 160
  log('D3 seam between cols 1-2', `gap ${a.x + a.w}..${b.x}, center ${seam}; ball at ${seam} spans ${seam - 7}..${seam + 7} -> overlaps BOTH (${seam - 7 < a.x + a.w} && ${seam + 7 > b.x})`);
}

// --- 10. D2 corner geometry --------------------------------------------------
{
  const minX = 100 - 7, maxY = 100 + 20 + 7;
  log('D2 corner point (expanded bottom-left)', `(${minX}, ${maxY}) — ball from below-right (97,131) to above-left (89,123) crosses it at t=0.5`);
}

// Probe test file — the defect cases, run against TODAY's code to capture red.
// Will be removed; the cases then move into to_fix.md and neon.test.js via TDD.
import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides, step, resolveBricks, makeBricks, createState,
  ballSpeed, BALL_R, BRICK_H, PADDLE_Y, PADDLE_H, WIDTH,
} from '../game/neon.js';

const EPS = 1e-9;

// --- D1: missing brick bounce + collant (no push-out) -----------------------
test('D1: ball hitting a brick bottom face bounces down, is pushed out, brick dies', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 72, h: 20, alive: true };
  state.bricks = [brick];
  state.ball = { x: 136, y: 131, r: BALL_R, vx: 0, vy: -ballSpeed(1) };
  step(state, 1 / 60);
  resolveBricks(state);
  assert.ok(state.ball.vy > 0, 'vy must flip from up to down');
  assert.equal(brick.alive, false, 'the hit brick must be destroyed');
  assert.equal(collides(state.ball, brick), false, 'ball must be pushed out of the brick');
});

// --- D2: face vs coin --------------------------------------------------------
test('D2a: side hit flips vx only (not vy)', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 72, h: 20, alive: true };
  state.bricks = [brick];
  state.ball = { x: 183, y: 110, r: BALL_R, vx: -ballSpeed(1), vy: 100 };
  step(state, 1 / 60);
  resolveBricks(state);
  assert.ok(state.ball.vx > 0, 'vx must flip from left to right');
  assert.equal(state.ball.vy, 100, 'vy must be untouched on a side hit');
  assert.equal(collides(state.ball, brick), false);
});

test('D2b: exact corner hit flips BOTH axes', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 72, h: 20, alive: true };
  state.bricks = [brick];
  // Ball crosses the expanded corner (93, 127) exactly, from below-right.
  state.ball = { x: 97, y: 131, r: BALL_R, vx: -300, vy: -300 };
  step(state, 8 / 300);
  resolveBricks(state);
  assert.ok(state.ball.vx > 0, 'vx must flip on a corner hit');
  assert.ok(state.ball.vy > 0, 'vy must flip on a corner hit');
  assert.equal(collides(state.ball, brick), false);
});

// --- D3: seam / double inversion --------------------------------------------
test('D3: seam between two bricks bounces exactly once (no double inversion)', () => {
  const state = createState(1);
  const bricks = makeBricks(1);
  const a = bricks[1]; // col 1, x=84..156
  const b = bricks[2]; // col 2, x=164..236
  state.bricks = [a, b];
  // Ball centered on the 8px gap (156..164), straddling both bricks, falling.
  state.ball = { x: 160, y: 40, r: BALL_R, vx: 0, vy: 300 };
  step(state, 1 / 30);
  resolveBricks(state);
  assert.ok(state.ball.vy < 0, 'vy must bounce back up, exactly once');
  assert.equal(collides(state.ball, a), false);
  assert.equal(collides(state.ball, b), false);
});

// --- D4: traversée (tunneling) + dt-independence ----------------------------
test('D4: 35.5px step (level 6, 50ms) fully crosses a 34px brick -> must still bounce', () => {
  const state = createState(6);
  const brick = { x: 100, y: 100, w: 72, h: 20, alive: true };
  state.bricks = [brick];
  state.ball = { x: 136, y: 128, r: BALL_R, vx: 0, vy: -ballSpeed(6) };
  step(state, 0.05); // moves 35.5px up -> y=92.5, past the brick (top 100-7=93)
  resolveBricks(state);
  assert.ok(state.ball.vy > 0, 'ball must bounce off the bottom face');
  assert.equal(brick.alive, false, 'the crossed brick must be destroyed');
  assert.equal(collides(state.ball, brick), false);
});

test('D4b: same crossing gives the same outcome at dt=1/144 and dt=0.05', () => {
  const run = (dt) => {
    const state = createState(6);
    const brick = { x: 100, y: 100, w: 72, h: 20, alive: true };
    state.bricks = [brick];
    state.ball = { x: 136, y: 128, r: BALL_R, vx: 0, vy: -ballSpeed(6) };
    step(state, dt);
    resolveBricks(state);
    return { vy: state.ball.vy, dead: brick.alive };
  };
  assert.deepEqual(run(1 / 144), run(0.05));
});

// --- D5: paddle --------------------------------------------------------------
test('D5a: fast ball crossing the whole paddle must bounce off its top', () => {
  const state = createState(7);
  state.ball = { x: WIDTH / 2, y: PADDLE_Y - BALL_R - 2, r: BALL_R, vx: 0, vy: ballSpeed(7) };
  step(state, 0.05); // 40px down: y=479, bottom edge 486 > paddle bottom 460
  assert.ok(state.ball.vy < 0, 'ball must bounce up off the paddle');
  assert.equal(state.ball.y, PADDLE_Y - BALL_R, 'ball must rest on the paddle top');
});

test('D5b: ball captured inside the paddle is pushed out through the top', () => {
  const state = createState(1);
  state.ball = { x: WIDTH / 2, y: PADDLE_Y + PADDLE_H / 2, r: BALL_R, vx: 0, vy: 100 };
  step(state, 0.05);
  assert.ok(state.ball.vy < 0, 'captured ball must bounce up');
  assert.equal(state.ball.y, PADDLE_Y - BALL_R, 'captured ball must exit through the top');
});

// --- D6: vitesse (norm preserved on paddle bounce) ---------------------------
test('D6: paddle edge hit keeps the ball at the level speed', () => {
  const state = createState(1);
  const speed = ballSpeed(1);
  state.ball = { x: state.paddle.x, y: PADDLE_Y - BALL_R - 4, r: BALL_R, vx: 0, vy: speed };
  step(state, 1 / 60);
  assert.ok(Math.abs(Math.hypot(state.ball.vx, state.ball.vy) - speed) < EPS,
    `|v| must stay ${speed}, got ${Math.hypot(state.ball.vx, state.ball.vy).toFixed(2)}`);
});

// --- D7: angle mort ----------------------------------------------------------
test('D7: dead-center paddle hit keeps a playable horizontal component', () => {
  const state = createState(1);
  state.ball = { x: WIDTH / 2, y: PADDLE_Y - BALL_R - 4, r: BALL_R, vx: 0, vy: ballSpeed(1) };
  step(state, 1 / 60);
  assert.notEqual(state.ball.vx, 0, 'center hit must not produce a vertical-only trajectory');
});

