const EPS = 0.01;

function sweptCircle(ball, x0, y0, x1, y1, brick) {
  const r = ball.r;
  const minX = brick.x - r, maxX = brick.x + brick.w + r;
  const minY = brick.y - r, maxY = brick.y + brick.h + r;
  const dx = x1 - x0, dy = y1 - y0;

  let tx1, tx2;
  if (dx === 0) {
    if (x0 <= minX || x0 >= maxX) return null;
    tx1 = -Infinity; tx2 = Infinity;
  } else {
    tx1 = (minX - x0) / dx;
    tx2 = (maxX - x0) / dx;
    if (tx1 > tx2) [tx1, tx2] = [tx2, tx1];
  }
  let ty1, ty2;
  if (dy === 0) {
    if (y0 <= minY || y0 >= maxY) return null;
    ty1 = -Infinity; ty2 = Infinity;
  } else {
    ty1 = (minY - y0) / dy;
    ty2 = (maxY - y0) / dy;
    if (ty1 > ty2) [ty1, ty2] = [ty2, ty1];
  }

  const tEntry = Math.max(tx1, ty1, 0);
  const tExit = Math.min(tx2, ty2, 1);
  if (tEntry > tExit) return null;

  const e1x = Math.max(tx1, 0);
  const e1y = Math.max(ty1, 0);
  if (tEntry === 0) {
    // Segment starts inside the expanded box: resolve by penetration.
    const penX = Math.min(x0 - minX, maxX - x0);
    const penY = Math.min(y0 - minY, maxY - y0);
    if (penX < penY) return { t: 0, nx: x0 - minX < maxX - x0 ? -1 : 1, ny: 0, corner: false, pen: penX };
    if (penY < penX) return { t: 0, nx: 0, ny: y0 - minY < maxY - y0 ? -1 : 1, corner: false, pen: penY };
    return { t: 0, nx: x0 - minX < maxX - x0 ? -1 : 1, ny: y0 - minY < maxY - y0 ? -1 : 1, corner: true, pen: penX };
  }

  const corner = e1x > 0 && e1y > 0 && Math.abs(e1x - e1y) < 1e-9;
  if (corner) return { t: tEntry, nx: dx >= 0 ? -1 : 1, ny: dy >= 0 ? -1 : 1, corner: true };
  if (e1x > e1y) return { t: tEntry, nx: dx >= 0 ? -1 : 1, ny: 0, corner: false };
  return { t: tEntry, nx: 0, ny: dy >= 0 ? -1 : 1, corner: false };
}
```

