```
export function resolveBricks(state) {
  const { ball } = state;
  const x0 = ball.px ?? ball.x;
  const y0 = ball.py ?? ball.y;
  const dx = ball.x - x0, dy = ball.y - y0;

  let best = null;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const hit = sweptCircle(ball, x0, y0, ball.x, ball.y, brick);
    if (!hit) continue;
    if (!best || hit.t < best.t || (hit.t === best.t && (hit.pen ?? Infinity) < (best.pen ?? Infinity))) {
      best = { brick, ...hit };
    }
  }
  if (!best) return [];

  const { brick, t, nx, ny, corner, pen } = best;
  if (t > 0) {
    ball.x = x0 + dx * t;
    ball.y = y0 + dy * t;
  } else if (!corner) {
    // push out along the resolution axis
    if (nx !== 0) ball.x += nx * (pen + EPS);
    else ball.y += ny * (pen + EPS);
  } else {
    ball.x += nx * (pen + EPS);
    ball.y += ny * (pen + EPS);
  }

  if (corner) { ball.vx = -ball.vx; ball.vy = -ball.vy; }
  else if (nx !== 0) ball.vx = -ball.vx;
  else ball.vy = -ball.vy;

  // Nudge along the reflected velocity so the ball no longer touches the brick.
  const sp = Math.hypot(ball.vx, ball.vy);
  if (sp > 0) {
    ball.x += (ball.vx / sp) * EPS;
    ball.y += (ball.vy / sp) * EPS;
  }

  brick.alive = false;
  return [brick];
}
```

