// TODO(#1): brick collision resolution (bounce + push-out) will live here.
// Increment D1: the ball that overlaps a brick bounces (vy flipped) and is
// pushed out of the rectangle. The face-selection and swept logic come next.
export function resolveBricks(state) {
  const { ball } = state;
  for (const brick of state.bricks) {
    if (!brick.alive || !collides(ball, brick)) continue;
    ball.vy = -Math.abs(ball.vy);
    // Push out along the axis of smallest penetration.
    const minX = brick.x - ball.r;
    const maxX = brick.x + brick.w + ball.r;
    const minY = brick.y - ball.r;
    const maxY = brick.y + brick.h + ball.r;
    const penX = Math.min(ball.x - minX, maxX - ball.x);
    const penY = Math.min(ball.y - minY, maxY - ball.y);
    if (penX < penY) {
      ball.x += (ball.x - minX < maxX - ball.x ? -1 : 1) * (penX + 0.01);
    } else {
      ball.y += (ball.y - minY < maxY - ball.y ? -1 : 1) * (penY + 0.01);
    }
    brick.alive = false;
    return [brick];
  }
  return [];
}

