content.text:
// neon.js — NÉON, a minimalist brick breaker (zero dependencies).
//
// Brick collision resolution (swept bounce + push-out) lives in the pure
// function `resolveBricks`; only the drawing remains in `frame()`.
//
// The module runs nothing on import: only `boot()` touches the DOM. Pure
// logic can therefore be imported from the tests (`node --test`) without a
// browser.

import { palette, brickColor } from './theme.js';
import { createGlowMap, drawGlow, GLOW_W, GLOW_H } from './bloom.js';

// --- Axis convention -------------------------------------------------------

// Screen coordinates, as the canvas defines them: the origin is the TOP-LEFT
// corner and **Y GROWS DOWNWARD**. So `y = 0` is the ceiling, `y = HEIGHT` the
// line through which the ball is lost, and a ball climbing toward the bricks
// has a NEGATIVE `vy`. Every sign in this file follows from that single
// choice — the launch velocity, each bounce, and the paddle test `vy > 0`.
//
// The constants below name the sign a velocity component takes per heading.
// Assert against them rather than against a bare `-1` / `1`: a test reading
// `Math.sign(ball.vy) === UP` states its intent, where a hard-coded `-1` only
// states an arithmetic fact and quietly means the opposite if the convention
// ever flips.
//
//   UP    (-1)  toward the ceiling and the bricks
//   DOWN  (+1)  toward the paddle and the loss line
//   LEFT  (-1)  toward x = 0
//   RIGHT (+1)  toward x = WIDTH

export const UP = -1;
export const DOWN = 1;
export const LEFT = -1;
export const RIGHT = 1;

// --- Field constants -------------------------------------------------------

export const WIDTH = 640;
export const HEIGHT = 480;

export const PADDLE_W = 96;
export const PADDLE_H = 12;
export const PADDLE_Y = HEIGHT - 32;

export const BALL_R = 7;

export const BRICK_ROWS = 5;
export const BRICK_COLS = 8;
export const BRICK_W = 72;
export const BRICK_H = 20;
export const BRICK_GAP = 8;
export const BRICK_TOP = 48;

const STORAGE_KEY = 'neon.best';

// --- State construction ----------------------------------------------------

// Builds the brick grid for a given level.
// The higher the level, the more points bricks are worth.
export function makeBricks(level = 1) {
  const bricks = [];
  const offsetX = (WIDTH - (BRICK_COLS * (BRICK_W + BRICK_GAP) - BRICK_GAP)) / 2;
  for (let row = 0; row < BRICK_ROWS; row++) {
    for (let col = 0; col < BRICK_COLS; col++) {
      bricks.push({
        x: offsetX + col * (BRICK_W + BRICK_GAP),
        y: BRICK_TOP + row * (BRICK_H + BRICK_GAP),
        w: BRICK_W,
        h: BRICK_H,
        row,
        alive: true,
        points: (BRICK_ROWS - row) * 10 * level,
      });
    }
  }
  return bricks;
}

// Ball speed as a function of the level (ramps up with each level).
export function ballSpeed(level = 1) {
  return 260 + (level - 1) * 90;
}

// Creates a fresh game state.
export function createState(level = 1) {
  const speed = ballSpeed(level);
  return {
    level,
    lives: 3,
    score: 0,
    combo: 0,
    best: 0,
    running: false,
    paddle: { x: (WIDTH - PADDLE_W) / 2, y: PADDLE_Y, w: PADDLE_W, h: PADDLE_H },
    ball: { x: WIDTH / 2, y: PADDLE_Y - BALL_R - 2, r: BALL_R, vx: speed * 0.5, vy: -speed },
    bricks: makeBricks(level),
  };
}

// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The bounce itself lives in `resolveBricks`.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Swept resolution: the ball sweeps the segment [previous, current]
// against each brick's box expanded by the ball radius (slab method). The
// EARLIEST contact across all bricks wins: one bounce per pass per axis, which
// also prevents the seam double inversion. The hit face comes from the slab
// entered last; equal entries mean the corner (both axes bounce).
const EPS = 0.01;

function sweptCircle(ball, x0, y0, x1, y1, brick) {
  const r = ball.r;
  const minX = brick.x - r;
  const maxX = brick.x + brick.w + r;
  const minY = brick.y - r;
  const maxY = brick.y + brick.h + r;
  const dx = x1 - x0;
  const dy = y1 - y0;

  let tx1, tx2;
  if (dx === 0) {
    if (x0 <= minX || x0 >= maxX) return null; // parallel to the slab, outside
    tx1 = -Infinity;
    tx2 = Infinity;
  } else {
    tx1 = (minX - x0) / dx;
    tx2 = (maxX - x0) / dx;
    if (tx1 > tx2) [tx1, tx2] = [tx2, tx1];
  }
  let ty1, ty2;
  if (dy === 0) {
    if (y0 <= minY || y0 >= maxY) return null;
    ty1 = -Infinity;
    ty2 = Infinity;
  } else {
    ty1 = (minY - y0) / dy;
    ty2 = (maxY - y0) / dy;
    if (ty1 > ty2) [ty1, ty2] = [ty2, ty1];
  }

  const tEntry = Math.max(tx1, ty1, 0);
  const tExit = Math.min(tx2, ty2, 1);
  if (tEntry > tExit) return null;

  if (tEntry === 0) {
    // Segment starts inside the expanded box: push out through the face of
    // smallest penetration (collant resolution).
    const penX = Math.min(x0 - minX, maxX - x0);
    const penY = Math.min(y0 - minY, maxY - y0);
    if (penX < penY) {
      return { t: 0, nx: x0 - minX < maxX - x0 ? -1 : 1, ny: 0, corner: false, pen: penX };
    }
    if (penY < penX) {
      return { t: 0, nx: 0, ny: y0 - minY < maxY - y0 ? -1 : 1, corner: false, pen: penY };
    }
    return {
      t: 0,
      nx: x0 - minX < maxX - x0 ? -1 : 1,
      ny: y0 - minY < maxY - y0 ? -1 : 1,
      corner: true,
      pen: penX,
    };
  }

  // The face entered last is the one hit (face vs corner). A corner is a
  // contact point that lies exactly on a box corner (the slab boundaries of
  // both axes meet there at the same instant).
  const cx = x0 + dx * tEntry;
  const cy = y0 + dy * tEntry;
  const onXBoundary = Math.abs(cx - minX) < 1e-9 || Math.abs(cx - maxX) < 1e-9;
  const onYBoundary = Math.abs(cy - minY) < 1e-9 || Math.abs(cy - maxY) < 1e-9;
  if (onXBoundary && onYBoundary) {
    // The contact is exactly a box corner: both axes bounce.
    return { t: tEntry, nx: dx >= 0 ? -1 : 1, ny: dy >= 0 ? -1 : 1, corner: true };
  }
  if (onXBoundary) return { t: tEntry, nx: dx >= 0 ? -1 : 1, ny: 0, corner: false };
  return { t: tEntry, nx: 0, ny: dy >= 0 ? -1 : 1, corner: false };
}

export function resolveBricks(state) {
  const { ball } = state;
  const x0 = ball.px ?? ball.x;
  const y0 = ball.py ?? ball.y;
  const dx = ball.x - x0;
  const dy = ball.y - y0;

  let best = null;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const hit = sweptCircle(ball, x0, y0, ball.x, ball.y, brick);
    if (!hit) continue;
    if (
      !best ||
      hit.t < best.t ||
      (hit.t === best.t && (hit.pen ?? Infinity) < (best.pen ?? Infinity))
    ) {
      best = { brick, ...hit };
    }
  }
  if (!best) return [];

  const { brick, t, nx, ny, corner, pen } = best;
  if (t > 0) {
    // Place the ball at the first contact.
    ball.x = x0 + dx * t;
    ball.y = y0 + dy * t;
  } else if (corner) {
    ball.x += nx * (pen + EPS);
    ball.y += ny * (pen + EPS);
  } else if (nx !== 0) {
    ball.x += nx * (pen + EPS);
  } else {
    ball.y += ny * (pen + EPS);
  }

  if (corner) {
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
  } else if (nx !== 0) {
    ball.vx = -ball.vx;
  } else {
    ball.vy = -ball.vy;
  }

  // Nudge along the reflected velocity so the ball no longer touches the brick.
  const sp = Math.hypot(ball.vx, ball.vy);
  if (sp > 0) {
    ball.x += (ball.vx / sp) * EPS;
    ball.y += (ball.vy / sp) * EPS;
  }

  brick.alive = false;
  return [brick];
}

// --- Score & combo (NOT covered by tests — debt #5) ------------------------

// Combo multiplier. UNBOUNDED today: a long combo makes the score blow up
// uncontrollably (see #5, expected improvement = clamp it).
export function comboMultiplier(combo) {
  return 1 + combo * 0.5;
}

// Points earned for breaking a brick, combo included.
export function scoreForBrick(brick, combo) {
  return Math.round(brick.points * comboMultiplier(combo));
}

// --- Best score persistence ------------------------------------------------

// Reads the best score from a localStorage-compatible storage.
// Robust to corrupted or missing storage: returns 0 instead of throwing.
export function loadBest(storage) {
  if (!storage) return 0;
  try {
    const raw = storage.getItem(STORAGE_KEY);
    const value = Number.parseInt(raw, 10);
    return Number.isFinite(value) && value > 0 ? value : 0;
  } catch {
    return 0;
  }
}

// Writes the best score if the current score beats it. Returns the updated best.
export function saveBest(storage, score) {
  const best = loadBest(storage);
  if (score > best && storage) {
    try {
      storage.setItem(STORAGE_KEY, String(score));
    } catch {
      // storage unavailable (private mode, quota): silently ignore
    }
    return score;
  }
  return best;
}

// --- Physics (movement + wall/paddle bounces) ------------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Brick collisions are resolved afterwards by
// `resolveBricks`, which sweeps the segment recorded here (`ball.px/py`).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  // Remember the pre-step position: the brick resolution sweeps the segment
  // from here to the new position (continuous collision detection).
  ball.px = ball.x;
  ball.py = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle: the ball must always exit through the top of the paddle. The
  // bounce is swept (the segment from the previous position to this one) so a
  // fast ball cannot cross the whole paddle in one step, and a ball captured
  // inside the rectangle is pushed back out through the top.
  if (ball.vy > 0) {
    const top = paddle.y - ball.r;
    const inside =
      ball.x + ball.r > paddle.x &&
      ball.x - ball.r < paddle.x + paddle.w &&
      ball.y + ball.r > paddle.y &&
      ball.y - ball.r < paddle.y + paddle.h;
    if (inside && ball.y <= paddle.y + paddle.h) {
      // Captured (or entered from above): resolve out through the top.
      ball.y = top;
      bounceOffPaddle(state);
    } else {
      // Swept: did the segment cross the paddle top within reach of the paddle?
      const dy = ball.y - ball.py;
      if (dy > 0 && ball.py <= top && ball.y >= top) {
        const t = (top - ball.py) / dy;
        const cx = ball.px + (ball.x - ball.px) * t;
        if (cx >= paddle.x - ball.r && cx <= paddle.x + paddle.w + ball.r) {
          ball.x = Math.max(paddle.x, Math.min(paddle.x + paddle.w, cx));
          ball.y = top;
          bounceOffPaddle(state);
        }
      }
    }
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

// Rebound off the paddle: the angle depends on where the paddle was hit, and
// the speed of a rebound is the speed of the level.
function bounceOffPaddle(state) {
  const { ball, paddle } = state;
  const speed = ballSpeed(state.level);
  // Where the paddle was hit: -1 (left edge) .. +1 (right edge).
  const hit = Math.max(-1, Math.min(1, (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2)));
  // A dead-center hit (hit === 0) must keep a playable horizontal component
  // instead of looping vertically between the paddle and the ceiling.
  const minVx = speed * 0.15;
  const vx = Math.sign(hit || 1) * Math.max(Math.abs(speed * 0.6 * hit), minVx);
  ball.vx = vx;
  // |v| stays equal to the level speed after the rebound.
  ball.vy = -Math.sqrt(speed * speed - vx * vx);
  state.combo = 0; // touching the paddle resets the combo
}

// --- Rendering (DOM): only drawing lives here; collision is pure logic -----

// Main render loop. Brick collisions were resolved by `resolveBricks` right
// after `step()` moved the ball; this loop only scores the destroyed bricks
// and draws the scene.
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Score the bricks destroyed by the collision resolution, once each.
  const destroyed = resolveBricks(state);
  for (const brick of destroyed) {
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }

  // Bricks: drawing only.
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

  // Paddle — color hard-coded instead of using the palette (inconsistency #6).
  ctx.fillStyle = '#00e5ff';
  ctx.fillRect(state.paddle.x, state.paddle.y, state.paddle.w, state.paddle.h);

  // Ball — also hard-coded (#6).
  ctx.fillStyle = '#39ff14';
  ctx.beginPath();
  ctx.arc(state.ball.x, state.ball.y, state.ball.r, 0, Math.PI * 2);
  ctx.fill();

  // HUD
  ctx.fillStyle = palette.text;
  ctx.font = '16px monospace';
  ctx.fillText(`Score ${state.score}`, 12, 24);
  ctx.fillText(`Best ${state.best}`, WIDTH - 110, 24);
  ctx.fillText(`Lives ${state.lives}`, WIDTH / 2 - 30, 24);
}

// --- Boot (browser entry point) --------------------------------------------

// Starts the game: wires up the canvas, the mouse and the animation loop.
// The only function that depends on the DOM; never called on import.
export function boot(doc = document) {
  const canvas = doc.getElementById('game');
  const ctx = canvas.getContext('2d');
  canvas.width = WIDTH;
  canvas.height = HEIGHT;

  const state = createState(1);
  state.best = loadBest(doc.defaultView?.localStorage ?? globalThis.localStorage);
  state.running = true;

  // Glow pass: a coarse offscreen light map, stretched over the field.
  const offscreen = doc.createElement('canvas');
  offscreen.width = GLOW_W;
  offscreen.height = GLOW_H;
  const glow = {
    map: createGlowMap(),
    image: offscreen.getContext('2d').createImageData(GLOW_W, GLOW_H),
  };

  // Move the paddle with the mouse.
  canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left - state.paddle.w / 2;
    state.paddle.x = Math.max(0, Math.min(WIDTH - state.paddle.w, x));
  });

  let last = performance.now();
  function loop(now) {
    const dt = Math.min((now - last) / 1000, 0.05);
    last = now;

    if (state.running) {
      const lost = step(state, dt);
      if (lost) {
        state.lives -= 1;
        state.combo = 0;
        if (state.lives <= 0) {
          state.best = saveBest(globalThis.localStorage, state.score);
          Object.assign(state, createState(state.level));
          state.best = loadBest(globalThis.localStorage);
        } else {
          // relaunch the ball
          state.ball = createState(state.level).ball;
        }
      }

      // Level cleared: all bricks broken
      if (state.bricks.every((b) => !b.alive)) {
        state.level += 1;
        state.bricks = makeBricks(state.level);
        state.ball = createState(state.level).ball;
      }
    }

    frame(ctx, state);
    drawGlow(ctx, glow, state, WIDTH, HEIGHT, offscreen);
    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);

  return state;
}

